(function(){'use strict';const defs={'night-room':['Quiet room tone',6,'Night story'],'night-phone':['Soft phone vibration',1.8,'Night story'],'night-shadow':['Low shadow swell',4,'Night story'],'night-release':['Gentle release chime',3,'Night story']};const cache=new Map;MotionAudio.registerSounds(defs,(ctx,key)=>{if(!defs[key])return null;const cacheKey=key+':'+ctx.sampleRate;if(cache.has(cacheKey))return cache.get(cacheKey);const d=defs[key][1],b=ctx.createBuffer(2,Math.ceil(ctx.sampleRate*d),ctx.sampleRate);let seed=42,low=0;for(let i=0;i<b.length;i++){const t=i/ctx.sampleRate,u=t/d;seed=(1664525*seed+1013904223)>>>0;const n=seed/2147483648-1;low+=.012*(n-low);let v=0;if(key==='night-room')v=low*.15+Math.sin(t*2*Math.PI*70)*.012;if(key==='night-phone')v=(Math.sin(t*2*Math.PI*135)+low)*.13*(Math.sin(t*9)>0?1:.15);if(key==='night-shadow')v=(Math.sin(t*2*Math.PI*48)*.075+low*.4)*Math.sin(Math.PI*u);if(key==='night-release')v=[392,493.88,587.33].reduce((a,f,j)=>a+(t>j*.16?Math.sin(2*Math.PI*f*(t-j*.16))*Math.exp(-(t-j*.16)*2):0),0)*.055;v*=Math.min(1,t*12,(d-t)*12);b.getChannelData(0)[i]=v;b.getChannelData(1)[i]=v}cache.set(cacheKey,b);if(cache.size>8)cache.delete(cache.keys().next().value);return b});})();
